import math
from dataclasses import dataclass

from src.mythosmini.config import WIKI_PPL_CAP
from src.mythosmini.leaderboard.entries import LeaderboardEntry


@dataclass(frozen=True)
class WikiNormalization:
    min_log: float
    max_log: float


def build_wiki_normalization(entries: list[LeaderboardEntry]) -> WikiNormalization:
    logs = [
        math.log(min(entry.wiki, WIKI_PPL_CAP))
        for entry in entries
        if entry.wiki is not None and entry.wiki > 0
    ]
    if not logs:
        return WikiNormalization(min_log=0.0, max_log=0.0)
    return WikiNormalization(min_log=min(logs), max_log=max(logs))


def wiki_score(entry: LeaderboardEntry, norm: WikiNormalization) -> float | None:
    if entry.wiki is None or entry.wiki <= 0 or norm.min_log == norm.max_log:
        return None
    capped_log = math.log(min(entry.wiki, WIKI_PPL_CAP))
    normalized = 1.0 - (capped_log - norm.min_log) / (norm.max_log - norm.min_log)
    return max(0.0, min(1.0, normalized)) * 100.0


def overall_score(entry: LeaderboardEntry, norm: WikiNormalization) -> float:
    wiki = wiki_score(entry, norm)
    if entry.blimp is None and entry.arc is None and wiki is None:
        return -1.0
    blimp = entry.blimp if entry.blimp is not None else 0.0
    arc = entry.arc if entry.arc is not None else 0.0
    wiki_value = wiki if wiki is not None else 0.0
    return (blimp + arc + wiki_value) / 3.0


def efficiency_score(entry: LeaderboardEntry, norm: WikiNormalization) -> float:
    score = overall_score(entry, norm)
    if score < 0 or entry.params <= 0:
        return -1.0
    return score / math.log10(entry.params + 1.0)
